import pdfplumber
from collections import Counter
pdf_path = '/root/employees_backup.pdf'
lengths = Counter()
with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        tables = page.extract_tables()
        for table in tables:
            for row in table:
                if row is None:
                    continue
                lengths[len(row)] += 1
print('row length distribution', lengths.most_common()[:10])
